//! Plan-emitter vectors: the same hand-built plans through the C++ planners of
//! `blocks/numbers/blocks.h` and the Rust port in `fp_core::numbers::blocks`. Generated by
//! `scripts/cpp_vectors/plan_emitters_vectors.cpp`.
//!
//! The file is a list of cases. Each case has a SETTING line, a VERDICT line, its parts and then
//! one ROUND line per round and one MSG line per message, every field in a fixed order. The Rust
//! side builds the same case with the ported planners and renders the same lines; all fields must
//! match, but the expected sizes on MSG lines (an average of positions, computed through libm) are
//! compared within a relative tolerance.

use std::rc::Rc;

use fp_core::numbers::blocks::*;
use fp_core::numbers::codes::{CodeSize, Radius};
use fp_core::numbers::plan::{MessageKind, Plan, PlanRound, Planned, Priced, TableDistances, TableTest};
use fp_core::numbers::real::{Big, Real};
use fp_core::numbers::round_names::R_LAST;
use fp_core::numbers::setting::{ErrorKind, Scope, Setting};

const VECTORS: &str = include_str!("../../fixtures/plan_emitters_vectors.txt");

fn big_hex(b: &Big) -> String {
    if b.is_zero() {
        return String::from("0");
    }
    b.w.iter().map(|w| format!("{:08x}", w)).collect::<Vec<_>>().join(",")
}

fn real_str(r: &Real) -> String {
    format!("{}@{}", big_hex(&r.m), r.e)
}

fn priced_int(p: Priced) -> u32 {
    match p {
        Priced::Nothing => 0,
        Priced::SettingAlone => 1,
        Priced::TheRoundItself => 2,
        Priced::AsSaid => 3,
        Priced::OnTheCallersWord => 4,
    }
}

fn table_test_int(t: TableTest) -> u32 {
    match t {
        TableTest::Later => 0,
        TableTest::OneTime => 1,
        TableTest::Link => 2,
    }
}

fn message_kind_int(k: MessageKind) -> u32 {
    match k {
        MessageKind::Scalars => 0,
        MessageKind::Answers => 1,
        MessageKind::Root => 2,
        MessageKind::Nonce => 3,
        MessageKind::Columns => 4,
        MessageKind::Salts => 5,
        MessageKind::Paths => 6,
        MessageKind::Head => 7,
    }
}

/// The fields of one round, in the C++ dump's order.
fn round_line(i: usize, r: &PlanRound) -> Vec<String> {
    vec![
        "ROUND".into(),
        i.to_string(),
        r.name.clone(),
        r.where_.clone(),
        (r.kind as u32).to_string(),
        (r.why as usize).to_string(),
        (r.scope as usize).to_string(),
        real_str(&r.error),
        (r.rests as u32).to_string(),
        r.work_bits.to_string(),
        r.count.to_string(),
        r.part.to_string(),
        r.message_bytes.to_string(),
        r.roots.to_string(),
        r.answers.to_string(),
        r.draw_e.to_string(),
        r.draw_nonzero.to_string(),
        r.draw_positions.to_string(),
        r.log_n.to_string(),
        r.draw_trits.to_string(),
        r.rows.to_string(),
        r.first_list.to_string(),
        r.combinations.to_string(),
        r.sharing.to_string(),
        priced_int(r.priced).to_string(),
        (r.group.said as u8).to_string(),
        r.group.main.log_n.to_string(),
        r.group.main.ell.to_string(),
        r.group.main.r.to_string(),
        r.group.mask.log_n.to_string(),
        r.group.mask.ell.to_string(),
        r.group.mask.r.to_string(),
        r.group.k.to_string(),
        r.group.h.to_string(),
        r.group.slots.to_string(),
        r.group.rule.to_string(),
        r.group.m.to_string(),
        (r.table.said as u8).to_string(),
        r.table.code.log_n.to_string(),
        r.table.code.ell.to_string(),
        r.table.code.r.to_string(),
        r.table.v.to_string(),
        r.table.answers.to_string(),
        r.table.distances.radius.to_string(),
        r.table.distances.later_radius.to_string(),
        r.table.distances.m_once.to_string(),
        r.table.distances.m_later.to_string(),
        table_test_int(r.table.test).to_string(),
    ]
}

fn setting_line(s: &Setting) -> Vec<String> {
    let mut v: Vec<String> = vec![
        "SETTING".into(),
        s.field_name.clone(),
        big_hex(&s.p),
        s.degree.to_string(),
        (s.circle as u8).to_string(),
        s.f_bytes.to_string(),
        s.e_bytes.to_string(),
        s.digest_bytes.to_string(),
        s.salt_bytes.to_string(),
        s.nonce_bytes.to_string(),
        s.position_bytes.to_string(),
        s.hash_block_bytes.to_string(),
        s.label_bytes.to_string(),
        s.chain_extra_bytes.to_string(),
        s.chain_free_words.to_string(),
        s.target.to_string(),
        s.instances.to_string(),
        s.samples.to_string(),
        (s.saved_coefficient as u8).to_string(),
    ];
    for i in 0..6 {
        for j in 0..3 {
            v.push(s.work[i][j].to_string());
        }
    }
    v
}

/// The lines of one case, as the C++ tool writes them.
fn render(plan: &Planned) -> Vec<Vec<String>> {
    let mut out = vec![setting_line(&plan.set)];
    out.push(vec![
        String::from("VERDICT"),
        format!("{}", plan.cause() as u32),
        String::from(plan.why_not()),
    ]);
    for (i, p) in plan.parts.iter().enumerate() {
        out.push(vec![String::from("PART"), i.to_string(), p.clone()]);
    }
    for (i, r) in plan.rounds.iter().enumerate() {
        out.push(round_line(i, r));
    }
    for (i, m) in plan.messages.iter().enumerate() {
        out.push(vec![
            String::from("MSG"),
            i.to_string(),
            m.name.clone(),
            m.where_.clone(),
            message_kind_int(m.kind).to_string(),
            m.bytes.to_string(),
            format!("{:x}", m.expected.to_bits()),
            m.count.to_string(),
            m.part.to_string(),
            (m.in_chain as u8).to_string(),
            m.hash_calls.to_string(),
        ]);
    }
    out
}

fn small() -> Setting {
    let mut s = Setting::goldilocks();
    s.target = 32;
    s
}

fn code(log_n: u32, ell: u64, r: u64) -> CodeSize {
    CodeSize { name: String::new(), log_n, ell, r, over_e: false }
}

fn group(name: &str, main: CodeSize, mask: CodeSize, k: u32, h: u32, slots: u64) -> GroupSize {
    GroupSize {
        name: String::from(name),
        main,
        mask,
        k,
        h,
        slots,
        rule: Radius::Johnson,
        m: 0,
    }
}

fn plain_shape(name: &str) -> GroupSize {
    group(name, code(4, 4, 4), CodeSize::default(), 0, 0, 1)
}

fn masked_shape(name: &str) -> GroupSize {
    group(name, code(4, 8, 4), code(4, 4, 2), 3, 1, 1)
}

fn sized(s: &Setting, shape: GroupSize) -> GroupSize {
    size_group(s, Scope::Request, &shape, &GroupLoad::default())
}

fn table_small() -> TableSize {
    TableSize {
        code: code(4, 4, 0),
        v: 3,
        answers: 1,
        distances: TableDistances { radius: 4, later_radius: 2, m_once: 0, m_later: 0 },
    }
}

fn sample(cube_bits: u32, groups: TestedIn) -> SampleSize {
    SampleSize { cube_bits, groups }
}

fn tree(name: &str, log_n: u32, leaf_bytes: u64) -> TreeSize {
    TreeSize { name: String::from(name), log_n, leaf_bytes, ..TreeSize::default() }
}

fn case_send() -> (String, Rc<Planned>) {
    let mut s = small();
    s.samples = 2;
    let plain = sized(&s, plain_shape("plain"));
    let masked = sized(&s, masked_shape("masked"));
    let mut p = Plan::new(s.clone());
    plan_send(
        &mut p,
        "send",
        &[sample(5, TestedIn::new(&plain)), sample(8, TestedIn::with_two(&plain, &masked))],
        2,
        true,
    );
    plan_chain_start(&mut p, "start", true);
    plan_file_item(&mut p, "header", "the file", MessageKind::Head, 128, 128.0, 3);
    plan_bat_sigma(&mut p, "sigma", 4);
    let mut sub = Plan::new(s);
    plan_bat_sigma(&mut sub, "sub", 2);
    let subf = sub.finish();
    p.begin_part("key");
    p.push_repeat(2);
    plan_chain(&mut p, &subf);
    p.pop_repeat();
    p.begin_part("proof");
    plan_none(&mut p, R_LAST, "last");
    (String::from("send"), p.finish())
}

fn case_bat() -> (String, Rc<Planned>) {
    let s = small();
    let plain = sized(&s, plain_shape("plain"));
    let masked = sized(&s, masked_shape("masked"));
    let mut p = Plan::new(s);
    p.compact = true;
    plan_bat(&mut p, "bat", &TestedIn::with_two(&plain, &masked), 5);
    plan_bat_sigma(&mut p, "sigma", 7);
    plan_split(&mut p, "split");
    (String::from("bat"), p.finish())
}

fn case_psc() -> (String, Rc<Planned>) {
    let s = small();
    let mut p = Plan::new(s);
    p.compact = true;
    plan_psc(&mut p, "psc", &PscSize { degree: vec![3, 3, 2, 2], degree_y: 2, values: 2, with_y: true });
    plan_psc(&mut p, "psc affine", &PscSize { degree: vec![3, 3], with_y: false, ..PscSize::default() });
    plan_zero(&mut p, "zero", 4);
    plan_line(&mut p, "line");
    plan_shift(&mut p, "shift", 9);
    plan_join(&mut p, "join", 3);
    plan_lkp(&mut p, "lkp", 5);
    plan_product_tree(&mut p, "tree", 2, 1);
    plan_batt(&mut p, "batt", 6, 3);
    (String::from("psc"), p.finish())
}

fn case_psc_open_coeff() -> (String, Rc<Planned>) {
    let mut s = small();
    s.saved_coefficient = false;
    let mut p = Plan::new(s);
    p.compact = true;
    plan_psc(&mut p, "psc open", &PscSize { degree: vec![3, 1], degree_y: 3, values: 1, with_y: true });
    plan_batt(&mut p, "batt", 5, 2);
    (String::from("psc_open_coeff"), p.finish())
}

fn case_lookup() -> (String, Rc<Planned>) {
    let s = small();
    let mut p = Plan::new(s);
    p.compact = true;
    plan_lookup(
        &mut p,
        "lookup",
        &LookupSize { v: 4, d: 3, mu: 3, shifted: true, live: 0, parts: vec![2, 2] },
    );
    plan_lookup(&mut p, "lookup small", &LookupSize { v: 1, d: 2, mu: 3, live: 2, ..LookupSize::default() });
    plan_lookup(&mut p, "lookup refused", &LookupSize { v: 2, d: 2, mu: 0, ..LookupSize::default() });
    (String::from("lookup"), p.finish())
}

fn case_rng() -> Vec<(String, Rc<Planned>)> {
    let mut s = small();
    s.set_work(ErrorKind::Small, Scope::Request, 5);
    let mut p = Plan::new(s.clone());
    plan_rng(&mut p, "rng", 10);
    let mut q = Plan::new(s);
    plan_rng(&mut q, "rng too many", u64::MAX);
    vec![(String::from("rng"), p.finish()), (String::from("rng_refuse"), q.finish())]
}

fn case_fold() -> (String, Rc<Planned>) {
    let s = small();
    let plain = sized(&s, plain_shape("plain"));
    let masked = sized(&s, masked_shape("masked"));
    let nomask = sized(&s, group("fold nomask", code(4, 8, 4), CodeSize::default(), 3, 0, 1));
    let mut p = Plan::new(s);
    p.compact = true;
    plan_fold(&mut p, "fold masked", &masked, 1);
    plan_fold(&mut p, "fold nomask", &nomask, 0);
    plan_fold(&mut p, "fold plain", &plain, 0);
    plan_loc(&mut p, "loc", &masked, &[tree("leaves", 4, 64)]);
    plan_base(&mut p, "base", &plain, &[tree("leaves", 4, 64)], 1);
    (String::from("fold"), p.finish())
}

fn case_cs() -> (String, Rc<Planned>) {
    let s = small();
    let plain = sized(&s, plain_shape("plain"));
    let masked = sized(&s, masked_shape("masked"));
    let mut p = Plan::new(s);
    plan_cs(&mut p, "cs", &plain, &masked, 6, 1, 2, &[tree("old rows", 4, 64)], 1);
    plan_base(&mut p, "base", &masked, &[tree("old rows", 4, 64)], 1);
    (String::from("cs"), p.finish())
}

fn case_iopp(name: &str, masks_ride: bool) -> (String, Rc<Planned>) {
    let s = small();
    let masked = sized(&s, masked_shape("test"));
    let mut p = Plan::new(s.clone());
    let t1 = plan_positions_default(&p, &analysis_group(&s, &masked).at.agree);
    let st = solve_stages(
        &mut p,
        &masked,
        t1,
        &[
            StageChoice { k: 1, h: 1, log_n: 8, mask_log_n: 8 },
            StageChoice { k: 0, h: 0, log_n: 12, mask_log_n: 12 },
        ],
    );
    let mut last = 0u64;
    plan_iopp(&mut p, "iopp", &st, &[tree("first", 4, 64)], 3, 1, masks_ride, &mut last);
    (String::from(name), p.finish())
}

fn case_record() -> Vec<(String, Rc<Planned>)> {
    let s = small();
    let mut p = Plan::new(s.clone());
    plan_record(&mut p, "record", &table_small());
    plan_seal(&mut p, "seal");
    let mut t = table_small();
    t.answers = 0;
    let mut q = Plan::new(s);
    plan_record(&mut q, "record zero", &t);
    vec![(String::from("record"), p.finish()), (String::from("record_zero"), q.finish())]
}

fn case_lin() -> (String, Rc<Planned>) {
    let s = small();
    let plain = sized(&s, plain_shape("plain"));
    let mut x = LinSize::new(
        sample(5, TestedIn::new(&plain)),
        sample(6, TestedIn::new(&plain)),
        sample(7, TestedIn::new(&plain)),
    );
    x.instances = 2;
    x.k_lo = 2;
    x.rows_log = 3;
    x.one_time = true;
    x.beside_w.push(sample(4, TestedIn::new(&plain)));
    x.beside_omega.push(sample(4, TestedIn::new(&plain)));
    x.roots_w = 2;
    x.roots_u = 1;
    x.roots_omega = 2;
    let mut p = Plan::new(s);
    plan_lin_first(&mut p, "lin", &x);
    plan_lin_shared(&mut p, "lin", &table_small(), &x, &tree("lin table", 4, 64));
    plan_seal(&mut p, "seal");
    (String::from("lin"), p.finish())
}

fn case_link() -> (String, Rc<Planned>) {
    let s = small();
    let plain = sized(&s, plain_shape("plain"));
    let u = sample(5, TestedIn::new(&plain));
    let mut p = Plan::new(s);
    plan_link(&mut p, "link", &table_small(), &u, &tree("link table", 4, 64));
    plan_seal(&mut p, "seal");
    (String::from("link"), p.finish())
}

fn case_instances() -> (String, Rc<Planned>) {
    let mut s = small();
    s.instances = 3;
    s.samples = 2;
    s.set_work(ErrorKind::Field, Scope::Request, 8);
    s.set_work(ErrorKind::Field, Scope::Shared, 4);
    let plain = sized(&s, plain_shape("plain"));
    let mut p = Plan::new(s);
    plan_bat(&mut p, "bat request", &TestedIn::new(&plain), 5);
    p.begin_scope(Scope::Shared);
    plan_bat(&mut p, "bat shared", &TestedIn::new(&plain), 5);
    p.begin_scope(Scope::Once);
    plan_bat(&mut p, "bat once", &TestedIn::new(&plain), 5);
    p.begin_scope(Scope::Request);
    plan_send(&mut p, "send", &[sample(5, TestedIn::new(&plain))], 1, true);
    plan_rng(&mut p, "rng", 3);
    (String::from("instances"), p.finish())
}

fn case_at_rule() -> (String, Rc<Planned>) {
    let s = small();
    let g = group_at(&plain_shape("at"), 4);
    let mut p = Plan::new(s);
    plan_fold(&mut p, "fold at", &g, 0);
    plan_loc(&mut p, "loc at", &g, &[]);
    (String::from("at_rule"), p.finish())
}

fn cases() -> Vec<(String, Rc<Planned>)> {
    let mut v = vec![
        case_send(),
        case_bat(),
        case_psc(),
        case_psc_open_coeff(),
        case_lookup(),
    ];
    v.extend(case_rng());
    v.push(case_fold());
    v.push(case_cs());
    v.push(case_iopp("iopp", false));
    v.push(case_iopp("iopp_ride", true));
    v.extend(case_record());
    v.push(case_lin());
    v.push(case_link());
    v.push(case_instances());
    v.push(case_at_rule());
    v
}

fn expected_cases() -> Vec<(String, Vec<Vec<String>>)> {
    let mut out: Vec<(String, Vec<Vec<String>>)> = Vec::new();
    for line in VECTORS.lines() {
        if line.is_empty() {
            continue;
        }
        let fields: Vec<String> = line.split('\t').map(String::from).collect();
        if fields[0] == "CASE" {
            out.push((fields[1].clone(), Vec::new()));
        } else {
            out.last_mut().expect("a line before the first CASE").1.push(fields);
        }
    }
    out
}

fn same_line(got: &[String], want: &[String]) -> bool {
    if got.len() != want.len() {
        return false;
    }
    if got[0] == "MSG" {
        // Field 6 is the expected size, an average over positions computed through libm: the C++
        // and Rust libraries may differ in the last bits.
        for i in 0..got.len() {
            if i != 6 && got[i] != want[i] {
                return false;
            }
        }
        let x = f64::from_bits(u64::from_str_radix(&got[6], 16).unwrap());
        let y = f64::from_bits(u64::from_str_radix(&want[6], 16).unwrap());
        let tol = 1e-9 * x.abs().max(y.abs()).max(1.0);
        (x - y).abs() <= tol
    } else {
        got == want
    }
}

#[test]
fn plan_emitter_vectors_match_the_cpp_planners() {
    let want = expected_cases();
    let got = cases();
    assert_eq!(got.len(), want.len(), "the number of cases");
    for (want_name, want_lines) in &want {
        let (name, plan) = got
            .iter()
            .find(|(n, _)| n == want_name)
            .unwrap_or_else(|| panic!("no Rust case named {}", want_name));
        assert_eq!(name, want_name);
        let got_lines = render(plan);
        assert_eq!(
            got_lines.len(),
            want_lines.len(),
            "case {}: line count (verdict {})",
            name,
            plan.why_not()
        );
        for (i, (g, w)) in got_lines.iter().zip(want_lines.iter()).enumerate() {
            assert!(
                same_line(g, w),
                "case {}, line {}: got {:?}, want {:?}",
                name,
                i + 1,
                g,
                w
            );
        }
    }
}
